-- Full 500-question AR Training bank and per-location 50-question rotation.
-- This is the forward-only database source of truth; no corpus files are committed.

begin;

create table if not exists public.ar_training_questions (
  id text primary key,
  bank_order integer not null unique check (bank_order between 1 and 500),
  question_type text not null,
  category text not null,
  prompt text not null,
  choices jsonb not null check (jsonb_typeof(choices) = 'array' and jsonb_array_length(choices) = 4),
  correct_index integer not null check (correct_index between 0 and 3),
  explanation text not null,
  source_title text not null,
  source_locator text not null,
  source_chunk_id text not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ar_training_location_cycles (
  location_id bigint primary key,
  cycle_number integer not null default 0 check (cycle_number >= 0),
  batch_index integer not null default 0 check (batch_index between 0 and 9),
  answered_question_ids jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.ar_training_questions enable row level security;
alter table public.ar_training_location_cycles enable row level security;
revoke all on public.ar_training_questions from anon, authenticated;
revoke all on public.ar_training_location_cycles from anon, authenticated;

